    32→- **Before**: O(n²) items, O(n) completion steps per level
    33→- **After**: O(n) items, O(1) completion per recursive step
    34→
    35→## Implementation Plan
    36→
    37→### 1. Leo Item Detection Logic
    38→
    39→Add method to identify Leo-eligible items:
    40→
    41→```perl
    42→method is_leo_eligible($item) {
    43→    my $rule = $item->rule;
    44→    my @rhs = $rule->rhs->@*;
    45→    
    46→    # Must be right-recursive: A -> α A β where β =>* ε
    47→    # Find if LHS appears in RHS and all symbols after it are nullable
    48→    for my $i (0 .. $#rhs) {
    49→        if ($rhs[$i] eq $rule->lhs) {
    50→            # Check if everything after position $i is nullable
    51→            my $all_nullable = 1;
    52→            for my $j ($i + 1 .. $#rhs) {
    53→                unless ($self->is_nullable($rhs[$j])) {
    54→                    $all_nullable = 0;
    55→                    last;
    56→                }
    57→            }
    58→            return 1 if $all_nullable;
    59→        }
    60→    }
    61→    return 0;
    62→}
    63→```
    64→
    65→### 2. Extended EarleyItem Class
    66→
    67→Add Leo support fields to EarleyItem:
    68→
    69→```perl
    70→class EarleyItem {
    71→    field $rule :param :reader;
    72→    field $dot_pos :param :reader = 0;
    73→    field $start_pos :param :reader = 0;
    74→    field $current_pos :param :reader :writer = 0;
    75→    field $matched_text :param :reader :writer = "";
    76→    field $semantic_value :param :reader = undef;
    77→    field $is_leo_item :param :reader = 0;           # NEW: Leo item flag
    78→    field $leo_base_item :param :reader = undef;     # NEW: Points to base item
    79→    field $transition_symbol :param :reader = undef; # NEW: What symbol transitions here
    80→
    81→    method is_leo_completion_item() {
    82→        # Leo completion items are complete items that can trigger Leo jumps
    83→        return $self->is_complete && $is_leo_item;
    84→    }
    85→
    86→    method create_leo_item($base_item, $symbol) {
    87→        # Create a Leo item representing a right-recursive chain
    88→        return EarleyItem->new(
    89→            rule => $base_item->rule,
    90→            dot_pos => $base_item->rule->rhs_length, # Dot at end
    91→            start_pos => $base_item->start_pos,
    92→            current_pos => $self->current_pos,
    93→            is_leo_item => 1,
    94→            leo_base_item => $base_item,
    95→            transition_symbol => $symbol
    96→        );
    97→    }
    98→}
    99→```
