   101→### 3. Leo Item Management in Parser
   102→
   103→Add Leo tracking to ScanlessEarleyParser:
   104→
   105→```perl
   106→class ScanlessEarleyParser {
   107→    field @grammar_rules;
   108→    field $ir_graph = ThreadedSeaOfNodes->new();
   109→    field @chart;
   110→    field $input_text;
   111→    field %nonterminals;
   112→    field %leo_items;        # NEW: Track Leo items by (position, symbol)
   113→    field %nullable_cache;   # NEW: Cache nullable computations
   114→
   115→    method is_nullable($symbol) {
   116→        return $nullable_cache{$symbol} if exists $nullable_cache{$symbol};
   117→        
   118→        # A symbol is nullable if it can derive the empty string
   119→        if ($symbol eq 'WS') {  # Your WS rule has empty production
   120→            return $nullable_cache{$symbol} = 1;
   121→        }
   122→        
   123→        # Check if any rule for this symbol has all nullable RHS
   124→        for my $rule (@grammar_rules) {
   125→            if ($rule->lhs eq $symbol) {
   126→                if ($rule->rhs_length == 0) {  # Empty RHS
   127→                    return $nullable_cache{$symbol} = 1;
   128→                }
   129→                
   130→                my $all_nullable = 1;
   131→                for my $rhs_symbol ($rule->rhs->@*) {
   132→                    unless ($self->is_nullable($rhs_symbol)) {
   133→                        $all_nullable = 0;
   134→                        last;
   135→                    }
   136→                }
   137→                if ($all_nullable) {
   138→                    return $nullable_cache{$symbol} = 1;
   139→                }
   140→            }
   141→        }
   142→        
   143→        return $nullable_cache{$symbol} = 0;
   144→    }
   145→
   146→    method get_leo_item($pos, $symbol) {
   147→        return $leo_items{"$pos:$symbol"};
   148→    }
   149→
   150→    method set_leo_item($pos, $symbol, $item) {
   151→        $leo_items{"$pos:$symbol"} = $item;
   152→    }
   153→}
   154→```
   155→
   156→### 4. Modified Completion Algorithm
   157→
   158→Replace the current completion method with Leo-aware version:
   159→
   160→```perl
   161→method complete($item, $pos, $agenda) {
   162→    DEBUG "Completing item " . $item->to_string;
   163→    my $rule = $item->rule;
   164→    my @child_values = $self->collect_child_values($item, $pos);
   165→
   166→    # Execute semantic action
   167→    my $semantic_value = undef;
   168→    try {
   169→        DEBUG "Executing semantic action for rule: " . $rule->to_string;
   170→        $semantic_value = $rule->execute_action(\@child_values, $ir_graph);
   171→    }
   172→    catch($e) {
   173→        warn "Error executing semantic action for rule " . $rule->id . ": $e";
   174→    }
   175→
   176→    $item->set_semantic_value($semantic_value);
   177→
   178→    # NEW: Check for Leo completion first
   179→    my $leo_item = $self->get_leo_item($item->start_pos, $rule->lhs);
   180→    if ($leo_item) {
   181→        DEBUG "Found Leo item for " . $rule->lhs . " at " . $item->start_pos;
   182→        # Leo completion: jump directly to the Leo item
   183→        my $new_item = $leo_item->advance();
   184→        $new_item->set_current_pos($pos);
   185→        $new_item->set_semantic_value($semantic_value);
   186→        push @$agenda, $new_item;
   187→        push @{$chart[$pos]}, $new_item;
   188→        return;  # Skip normal completion
   189→    }
   190→
   191→    # Normal Earley completion (unchanged)
   192→    for my $waiting_item (@{$chart[$item->start_pos]}) {
   193→        next if $waiting_item->is_complete;
   194→        next unless defined $waiting_item->next_symbol;
   195→        next unless $waiting_item->next_symbol eq $rule->lhs;
   196→
   197→        my $new_item = $waiting_item->advance;
   198→        $new_item->set_current_pos($pos);
   199→        
   200→        # NEW: Check if this creates a Leo-eligible situation
   201→        if ($self->is_leo_eligible($new_item)) {
   202→            my $leo_item = $new_item->create_leo_item($waiting_item, $rule->lhs);
   203→            $self->set_leo_item($waiting_item->start_pos, $rule->lhs, $leo_item);
   204→            DEBUG "Created Leo item for " . $rule->lhs . " at " . $waiting_item->start_pos;
   205→        }
   206→        
   207→        push @$agenda, $new_item;
   208→        push @{$chart[$pos]}, $new_item;
   209→    }
   210→}
   211→```
   212→
   213→### 5. Enhanced Prediction
   214→
   215→Update prediction method to detect Leo-eligible predictions:
   216→
   217→```perl
   218→method predict($item, $pos, $agenda) {
   219→    my $next_sym = $item->next_symbol;
   220→    DEBUG "Predicting for symbol: $next_sym at position $pos";
   221→
   222→    for my $rule (@grammar_rules) {
   223→        if ($rule->lhs eq $next_sym) {
   224→            DEBUG "Found rule to predict: " . $rule->to_string;
   225→            
   226→            # Check if already predicted
   227→            my $already_predicted = 0;
   228→            for my $existing_item (@{$chart[$pos]}) {
   229→                if ($existing_item->rule == $rule && 
   230→                    $existing_item->start_pos == $pos && 
   231→                    $existing_item->dot_pos == 0) {
   232→                    $already_predicted = 1;
   233→                    last;
   234→                }
   235→            }
   236→            next if $already_predicted;
   237→
   238→            my $predicted_item = EarleyItem->new(
   239→                rule => $rule,
   240→                start_pos => $pos,
   241→                current_pos => $pos
   242→            );
   243→
   244→            # NEW: Check if this prediction could benefit from Leo items
   245→            if ($self->is_leo_eligible($predicted_item)) {
   246→                DEBUG "Predicted item is Leo-eligible: " . $rule->to_string;
   247→            }
   248→
   249→            push @$agenda, $predicted_item;
   250→            push @{$chart[$pos]}, $predicted_item;
   251→        }
   252→    }
   253→}
   254→```
   255→
   256→## Testing Leo Items
   257→
   258→### Performance Test
   259→
   260→Create test cases with progressively longer strings:
   261→
   262→```perl
   263→#!/usr/bin/env perl
   264→use v5.42;
   265→use Time::HiRes qw(time);
   266→
   267→my $parser = ScanlessEarleyParser->new();
   268→
   269→# Test strings of different lengths
   270→my @test_cases = (
   271→    '"hello"',                    # 5 chars
   272→    '"' . 'x' x 50 . '"',        # 50 chars  
   273→    '"' . 'y' x 500 . '"',       # 500 chars
   274→    '"' . 'z' x 5000 . '"',      # 5000 chars
   275→);
   276→
   277→for my $test_string (@test_cases) {
   278→    my $length = length($test_string) - 2;  # Subtract quotes
   279→    
   280→    my $start_time = time();
   281→    my $ir_graph = $parser->parse("print $test_string;");
   282→    my $elapsed = time() - $start_time;
   283→    
   284→    printf "String length: %d chars, Parse time: %.4f seconds\n", 
   285→           $length, $elapsed;
   286→}
   287→```
   288→
   289→### Expected Results
   290→
   291→**Before Leo Items**:
   292→```
   293→String length: 5 chars, Parse time: 0.0010 seconds
   294→String length: 50 chars, Parse time: 0.0250 seconds  
   295→String length: 500 chars, Parse time: 2.5000 seconds (quadratic growth)
   296→String length: 5000 chars, Parse time: 250+ seconds (unusable)
   297→```
   298→
   299→**After Leo Items**:
   300→```
   301→String length: 5 chars, Parse time: 0.0008 seconds
   302→String length: 50 chars, Parse time: 0.0080 seconds
   303→String length: 500 chars, Parse time: 0.0800 seconds (linear growth)
   304→String length: 5000 chars, Parse time: 0.8000 seconds (manageable)
   305→```
   306→
   307→## Debugging Leo Items
   308→
   309→Add debug output to trace Leo item creation and usage:
   310→
   311→```perl
   312→method complete($item, $pos, $agenda) {
   313→    # ... existing code ...
   314→    
   315→    my $leo_item = $self->get_leo_item($item->start_pos, $rule->lhs);
   316→    if ($leo_item) {
   317→        DEBUG "LEO JUMP: Found Leo item for " . $rule->lhs . 
   318→              " at " . $item->start_pos . 
   319→              " -> jumping to position " . $pos;
   320→        # ... Leo completion logic ...
   321→    }
   322→}
   323→```
   324→
   325→## Implementation Notes
   326→
   327→### Correctness Considerations
   328→
   329→1. **Semantic Actions**: Leo items must preserve semantic action execution order
   330→2. **Ambiguity**: Leo items work best with unambiguous right recursion
   331→3. **Left Recursion**: Leo items don't help with left-recursive rules
   332→
   333→### Edge Cases to Test
   334→
   335→1. **Empty Rules**: Rules with nullable right-hand sides
   336→2. **Mixed Recursion**: Rules with both left and right recursion
   337→3. **Nested Recursion**: Multiple levels of recursive calls
   338→4. **Ambiguous Grammars**: Multiple derivations for the same input
   339→
   340→### Performance Monitoring
   341→
   342→Add metrics to track Leo item effectiveness:
   343→
   344→```perl
   345→field $leo_items_created = 0;
   346→field $leo_jumps_performed = 0;
   347→field $items_avoided = 0;
   348→
   349→method report_leo_stats() {
   350→    say "Leo Items Created: $leo_items_created";
   351→    say "Leo Jumps Performed: $leo_jumps_performed";
   352→    say "Items Avoided: $items_avoided";
   353→    say "Efficiency Gain: " . ($items_avoided / ($leo_items_created || 1));
   354→}
   355→```
   356→
   357→## Alternative Approach: Left Recursion
   358→
   359→Instead of implementing Leo items, you could convert right recursion to left recursion:
   360→
   361→```perl
   362→# Current (right recursive):
   363→CharSeq -> Char CharSeq
   364→CharSeq -> Char
   365→
   366→# Alternative (left recursive):
   367→CharSeq -> CharSeq Char  
   368→CharSeq -> Char
   369→```
   370→
   371→**Pros**: Simpler implementation, naturally linear
   372→**Cons**: Changes semantic action order, requires grammar restructuring
   373→
   374→## Integration with Distributed Parser
   375→
   376→Leo items provide several benefits for the distributed parsing system:
   377→
   378→1. **Predictable Performance**: Linear parsing time enables reliable throughput estimates
   379→2. **Memory Efficiency**: Fewer items created means less memory pressure
   380→3. **Scalability**: Better single-node performance improves overall cluster performance
   381→4. **Large File Support**: Can handle very large source files without timeout
   382→
   383→## Implementation Priority
   384→
   385→**High Priority**: Implement Leo items for CharSeq rules (biggest performance gain)
   386→**Medium Priority**: Extend to other right-recursive patterns in the grammar
   387→**Low Priority**: Add comprehensive Leo item debugging and monitoring tools
   388→
   389→## References
   390→
